def has_multi_table(
        self, connection, table_names, schema=None, dblink=None, **kw
    ):
        """Supported kw arguments are: ``dblink`` to reflect via a db link."""

        owner = schema or self.default_schema_name
        db_tns = [self.denormalize_name(tn) for tn in table_names]
        params = {
            "table_names": db_tns,
            "owner": self.denormalize_schema_name(owner),
        }
        cursor = self._execute_reflection(
            connection,
            self._has_multi_table_query,
            dblink,
            returns_long=False,
            params=params,
        )
        existing = set(cursor.scalars().all())
        retval = {
            (schema, table): db_tn in existing
            for table, db_tn in zip(table_names, db_tns)
        }
        return retval.items()

def _validate_float_format(
        self, fmt: FloatFormatType | None
    ) -> FloatFormatType | None:
        """
        Validates and processes the float_format argument.
        Converts new-style format strings to callables.
        """
        if fmt is None or callable(fmt):
            return fmt

        if isinstance(fmt, str):
            if "%" in fmt:
                # Keeps old-style format strings as they are (C code handles them)
                return fmt
            else:
                try:
                    _ = fmt.format(1.0)  # Test with an arbitrary float
                    return fmt.format
                except (ValueError, KeyError, IndexError) as e:
                    raise ValueError(f"Invalid new-style format string {fmt!r}") from e

        raise ValueError("float_format must be a string or callable")

def _load_on_pk_identity(self, session, query, primary_key_identity, **kw):
        """Load the given primary key identity from the database."""

        mapper = query._raw_columns[0]._annotations["parententity"]

        _get_clause, _get_params = mapper._get_clause

        def setup(query):
            _lcl_get_clause = _get_clause
            q = query._clone()
            q._get_condition()
            q._order_by = None

            # None present in ident - turn those comparisons
            # into "IS NULL"
            if None in primary_key_identity:
                nones = {
                    _get_params[col].key
                    for col, value in zip(
                        mapper.primary_key, primary_key_identity
                    )
                    if value is None
                }
                _lcl_get_clause = sql_util.adapt_criterion_to_null(
                    _lcl_get_clause, nones
                )

            # TODO: can mapper._get_clause be pre-adapted?
            q._where_criteria = (
                sql_util._deep_annotate(_lcl_get_clause, {"_orm_adapt": True}),
            )

            for fn in self._post_criteria:
                q = fn(q)
            return q

        # cache the query against a key that includes
        # which positions in the primary key are NULL
        # (remember, we can map to an OUTER JOIN)
        bq = self.bq

        # add the clause we got from mapper._get_clause to the cache
        # key so that if a race causes multiple calls to _get_clause,
        # we've cached on ours
        bq = bq._clone()
        bq._cache_key += (_get_clause,)

        bq = bq.with_criteria(
            setup, tuple(elem is None for elem in primary_key_identity)
        )

        params = {
            _get_params[primary_key].key: id_val
            for id_val, primary_key in zip(
                primary_key_identity, mapper.primary_key
            )
        }

        result = list(bq.for_session(self.session).params(**params))
        l = len(result)
        if l > 1:
            raise orm_exc.MultipleResultsFound()
        elif l:
            return result[0]
        else:
            return None

def inf_to_nan(func):
    """Decorate function to return nan if it returns inf"""
    def wrap(*a, **kw):
        v = func(*a, **kw)
        if not np.isfinite(v):
            return np.nan
        return v
    return wrap

