def _set_sparse(self, row, col, x):
        """Dispatch to one of the _set_<type>X<type>_sparse methods."""
        if isinstance(row, INT_TYPES):
            if isinstance(col, INT_TYPES):
                if x.shape[0] * x.shape[1] != 1:
                    raise ValueError("Trying to assign a sequence to an item")
                val = self.dtype.type(x.toarray().item())
                return self._set_intXint(row, col, val)
            elif isinstance(col, slice):
                return self._set_intXslice_sparse(row, col, x)
            else:
                return self._set_intXarray_sparse(row, col, x)
        elif isinstance(row, slice):
            if isinstance(col, INT_TYPES):
                return self._set_sliceXint_sparse(row, col, x)
            elif isinstance(col, slice):
                return self._set_sliceXslice_sparse(row, col, x)
            else:
                return self._set_sliceXarray_sparse(row, col, x)
        # row must be an array.
        if isinstance(col, INT_TYPES):
            return self._set_arrayXint_sparse(row, col, x)
        elif isinstance(col, slice):
            return self._set_arrayXslice_sparse(row, col, x)
        # col must be an array.
        if row.ndim == 2 and row.shape[1] == 1 and (col.ndim == 1 or col.shape[0] == 1):
            return self._set_columnXarray_sparse(row[:, 0], col.reshape(-1), x)
        if col.ndim == 2 and col.shape[1] == 1 and (row.ndim == 1 or row.shape[0] == 1):
            return self._set_columnXarray_sparse(row.reshape(-1), col[:, 0], x.T)
        row, col = _broadcast_arrays(row, col)
        if row.shape != col.shape:
            raise IndexError("row and column index arrays mismatch")
        if row.ndim == 1:
            row = row[None]
            col = col[None]
        return self._set_arrayXarray_sparse(row, col, x)

def _conv_ops(x_shape, h_shape, mode):
    """
    Find the number of operations required for direct/fft methods of
    convolution. The direct operations were recorded by making a dummy class to
    record the number of operations by overriding ``__mul__`` and ``__add__``.
    The FFT operations rely on the (well-known) computational complexity of the
    FFT (and the implementation of ``_freq_domain_conv``).

    """
    if mode == "full":
        out_shape = [n + k - 1 for n, k in zip(x_shape, h_shape)]
    elif mode == "valid":
        out_shape = [abs(n - k) + 1 for n, k in zip(x_shape, h_shape)]
    elif mode == "same":
        out_shape = x_shape
    else:
        raise ValueError("Acceptable mode flags are 'valid',"
                         f" 'same', or 'full', not mode={mode}")

    s1, s2 = x_shape, h_shape
    if len(x_shape) == 1:
        s1, s2 = s1[0], s2[0]
        if mode == "full":
            direct_ops = s1 * s2
        elif mode == "valid":
            direct_ops = (s2 - s1 + 1) * s1 if s2 >= s1 else (s1 - s2 + 1) * s2
        elif mode == "same":
            direct_ops = (s1 * s2 if s1 < s2 else
                          s1 * s2 - (s2 // 2) * ((s2 + 1) // 2))
    else:
        if mode == "full":
            direct_ops = min(_prod(s1), _prod(s2)) * _prod(out_shape)
        elif mode == "valid":
            direct_ops = min(_prod(s1), _prod(s2)) * _prod(out_shape)
        elif mode == "same":
            direct_ops = _prod(s1) * _prod(s2)

    full_out_shape = [n + k - 1 for n, k in zip(x_shape, h_shape)]
    N = _prod(full_out_shape)
    fft_ops = 3 * N * np.log(N)  # 3 separate FFTs of size full_out_shape
    return fft_ops, direct_ops

def _check_X(self, X):
        """Validate X, used only in predict* methods."""
