def changelog(token, revision_range):
    """👩 Get change log for provided revision range

    \b
    Example:

    \b
    $ spin authors -t $GH_TOKEN --revision-range v1.25.0..v1.26.0
    """
    try:
        from git.exc import GitError
        from github.GithubException import GithubException
        changelog = _get_numpy_tools(pathlib.Path('changelog.py'))
    except ModuleNotFoundError as e:
        raise click.ClickException(
            f"{e.msg}. Install the missing packages to use this command."
        )
    click.secho(
        f"Generating change log for range {revision_range}",
        bold=True, fg="bright_green",
    )
    try:
        changelog.main(token, revision_range)
    except GithubException as e:
        raise click.ClickException(
            f"GithubException raised with status: {e.status} "
            f"and message: {e.data['message']}"
        )
    except GitError as e:
        raise click.ClickException(
            f"Git error in command `{' '.join(e.command)}` "
            f"with error message: {e.stderr}"
        )

def _fetch_multi_pk_constraint(
        self, connection, owner, names, schema, name_map, result, exec_opts
    ):
        """Execute the unified pk_constraint select for one catalog pass.

        Used by :meth:`.get_multi_pk_constraint` for both the main DB
        pass and the tempdb pass (with ``schema_translate_map`` set).
        """
        s = self._pk_constraint_select()

        rp = connection.execute(
            s,
            {"owner": owner, "filter_names": names},
            execution_options=exec_opts,
        )

        for row in rp.mappings():
            table_name = name_map(row["table_name"])
            key = (schema, table_name)
            if key not in result:
                result[key] = {
                    "constrained_columns": [],
                    "name": row["constraint_name"],
                    "dialect_options": {
                        "mssql_clustered": row["index_type"] == 1
                    },
                }
            result[key]["constrained_columns"].append(row["column_name"])

        for n in names:
            key = (schema, name_map(n))
            if key not in result:
                result[key] = ReflectionDefaults.pk_constraint()

def _sanitize_non_ordered(data) -> None:
    """
    Raise only for unordered sets, e.g., not for dict_keys
    """
    if isinstance(data, (set, frozenset)):
        raise TypeError(f"'{type(data).__name__}' type is unordered")

def _use_cache(self, estimator):
        """Return True if using a cache is beneficial, thus when a response method will
        be called several time.
        """
        if len(self._scorers) == 1:  # Only one scorer
            return False

        counter = Counter(
            [
                _check_response_method(estimator, scorer._response_method).__name__
                for scorer in self._scorers.values()
                if isinstance(scorer, _BaseScorer)
            ]
        )
        if any(val > 1 for val in counter.values()):
            # The exact same response method or iterable of response methods
            # will be called more than once.
            return True

        return False

