def _ensure_constraint(self, trial):
        """Make sure the parameters lie between the limits."""
        mask = np.bitwise_or(trial > 1, trial < 0)
        if oob := np.count_nonzero(mask):
            trial[mask] = self.random_number_generator.uniform(size=oob)

