    print(f"\n{name} pulled in:")
    for lib in categorized['shared']:
        print(f"  {strip_prefix(lib)}")

    if args.show_stdlib and categorized['stdlib']:
        print(f"\n  stdlib extensions ({len(categorized['stdlib'])}):")
