def get_adaptive_int(self):
        """
        Fetch an int from the stream.

        :return: a 32-bit unsigned `int`.
        """
        byte = self.get_bytes(1)
        if byte == max_byte:
            return util.inflate_long(self.get_binary())
        byte += self.get_bytes(3)
        return struct.unpack(">I", byte)[0]

def _is_int_type(x):
    """
    Check if input is of a scalar integer type (so ``5`` and ``array(5)`` will
    pass, while ``5.0`` and ``array([5])`` will fail.
    """
    try:
        operator.index(x)
    except TypeError:
        return False
    else:
        return True

def equals(self, other: Any) -> bool:
        """
        Determines if two Index objects contain the same elements.
        """
        if self.is_(other):
            return True

        if not isinstance(other, Index):
            return False
        elif other.dtype.kind in "iufc":
            return False
        elif not isinstance(other, type(self)):
            if other.dtype == object:
                # Use the cached inferred_type as a cheap pre-filter
                inferred = other.inferred_type
                compatible: tuple[str, ...]
                if self.dtype.kind == "M":
                    compatible = ("datetime", "datetime64", "date")
                elif self.dtype.kind == "m":
                    compatible = ("timedelta", "timedelta64")
                else:
                    compatible = ("period",)
                if inferred not in compatible:
                    return False
                converted = lib.maybe_convert_objects(
                    np.asarray(other), convert_non_numeric=True
                )
                converted = ensure_wrapped_if_datetimelike(converted)
                if isinstance(converted, type(self._data)):
                    other = type(self)._simple_new(converted)
                elif self.dtype.kind == "M" and inferred == "date":
                    # GH#65056
                    warnings.warn(
                        "Inferring datetime64 from data containing "
                        "datetime.date objects is deprecated. In a future "
                        "version, these will be left as object dtype. Use "
                        "pd.to_datetime to explicitly convert to datetime64.",
                        Pandas4Warning,
                        stacklevel=find_stack_level(),
                    )
                    try:
                        other = type(self)(other)
                    except (ValueError, TypeError, OverflowError):
                        return False
            elif isinstance(other.dtype, CategoricalDtype):
                other = cast("CategoricalIndex", other)
                cat_vals = np.asarray(other.categories)
                if cat_vals.dtype == object:
                    converted = lib.maybe_convert_objects(
                        cat_vals, convert_non_numeric=True
                    )
                    converted = ensure_wrapped_if_datetimelike(converted)
                else:
                    converted = ensure_wrapped_if_datetimelike(cat_vals)
                if isinstance(converted, type(self._data)):
                    try:
                        other = type(self)(other)
                    except (ValueError, TypeError, OverflowError):
                        return False
                elif (
                    self.dtype.kind == "M"
                    and cat_vals.dtype == object
                    and lib.infer_dtype(other.categories) == "date"
                ):
                    # GH#65056
                    warnings.warn(
                        "Inferring datetime64 from data containing "
                        "datetime.date objects is deprecated. In a "
                        "future version, these will be left as object "
                        "dtype. Use pd.to_datetime to explicitly "
                        "convert to datetime64.",
                        Pandas4Warning,
                        stacklevel=find_stack_level(),
                    )
                    try:
                        other = type(self)(other)
                    except (ValueError, TypeError, OverflowError):
                        return False

        if type(self) != type(other):
            return False
        elif self.dtype == other.dtype:
            return lib.array_equivalent_bytes(self.asi8, other.asi8)
        elif (self.dtype.kind == "M" and self.tz == other.tz) or self.dtype.kind == "m":  # type: ignore[attr-defined]
            # different units, otherwise matching
            try:
                # TODO: do this at the EA level?
                left, right = self._data._ensure_matching_resos(other._data)  # type: ignore[union-attr]
            except (OutOfBoundsDatetime, OutOfBoundsTimedelta):
                return False
            else:
                return lib.array_equivalent_bytes(left.view("i8"), right.view("i8"))
        return False

def _has_redundant_generator_parentheses(node: LN) -> bool:
    """Whether `node` adds parentheses around a parenthesized generator."""
    if (
        node.type != syms.atom
        or len(node.children) != 3
        or not is_lpar_token(node.children[0])
        or not is_rpar_token(node.children[-1])
    ):
        return False

    middle = node.children[1]
    return is_generator(middle) or _has_redundant_generator_parentheses(middle)

def _fix_output(output, usemask=True, asrecarray=False):
    """
    Private function: return a recarray, an ndarray, a MaskedArray
    or a MaskedRecords depending on the input parameters
    """
    if not isinstance(output, ma.MaskedArray):
        usemask = False
    if usemask:
        if asrecarray:
            output = output.view(mrec.MaskedRecords)
    else:
        output = ma.filled(output)
        if asrecarray:
            output = output.view(np.recarray)
    return output

def _compatible_boolean_index(idx, desired_ndim):
    """Check for boolean array or array-like. peek before asarray for array-like"""
    # use attribute ndim to indicate a compatible array and check dtype
    # if not, look at 1st element as quick rejection of bool, else slower asanyarray
    if not hasattr(idx, 'ndim'):
        # is first element boolean?
        try:
            ix = next(iter(idx), None)
            for _ in range(desired_ndim):
                if isinstance(ix, bool):
                    break
                ix = next(iter(ix), None)
            else:
                return None
        except TypeError:
            return None
        # since first is boolean, construct array and check all elements
        idx = np.asanyarray(idx)

    if idx.dtype.kind == 'b':
        return idx
    return None

def _row_limit_clause(self, select, **kw):
        """Oracle Database 12c supports OFFSET/FETCH operators
        Use it instead subquery with row_number

        """

        if (
            select._fetch_clause is not None
            or not self.dialect._supports_offset_fetch
        ):
            return super()._row_limit_clause(
                select, use_literal_execute_for_simple_int=True, **kw
            )
        else:
            return self.fetch_clause(
                select,
                fetch_clause=self._get_limit_or_fetch(select),
                use_literal_execute_for_simple_int=True,
                **kw,
            )

def get_temp_table_names(self, connection, dblink=None, **kw):
        """Supported kw arguments are: ``dblink`` to reflect via a db link."""
        schema = self.denormalize_schema_name(self.default_schema_name)

        query = select(dictionary.all_tables.c.table_name)
        if self.exclude_tablespaces:
            query = query.where(
                func.coalesce(
                    dictionary.all_tables.c.tablespace_name, "no tablespace"
                ).not_in(self.exclude_tablespaces)
            )
        query = query.where(
            dictionary.all_tables.c.owner == schema,
            dictionary.all_tables.c.iot_name.is_(null()),
            dictionary.all_tables.c.duration.is_not(null()),
        )

        result = self._execute_reflection(
            connection, query, dblink, returns_long=False
        ).scalars()
        return [self.normalize_name(row) for row in result]

def from_header(cls, value: str | None) -> te.Self:
        """Parse a header value and create an instance of this class.

        .. versionadded:: 3.2
        """
        if not value:
            return cls()

        result = []

        for item in parse_list_header(value):
            item, options = parse_options_header(item)

            if "q" in options:
                # pop q, remaining options are reconstructed
                q_str = options.pop("q").strip(" \t")

                if _q_value_re.fullmatch(q_str) is None:
                    # ignore an invalid q
                    continue

                q = float(q_str)
            else:
                q = 1

            if options:
                # reconstruct the value with remaining options
                item = dump_options_header(item, options)

            result.append((item, q))

        return cls(result)

