        if max_width == 0:
            return "[" + ", ".join(fmt_values) + "]"

        parts = ["["]
        cur_col_len = 1  # account for the opening bracket
        start = True
        for val in fmt_values:
            if not start:
                if cur_col_len + 2 + len(val) > max_width:
                    parts.append(",\n ")
                    cur_col_len = 1  # 1 space indent
                else:
                    parts.append(", ")
                    cur_col_len += 2
            parts.append(val)
            cur_col_len += len(val)
            start = False
        parts.append("]")
        return "".join(parts)

