def _normalize_out(out, nout):
    """Validate ``out`` and return it as a tuple of length ``nout``.

    Entries may be None, meaning that output should be allocated for the user,
    matching the behavior of a plain ufunc.

    """
    if out is _NO_VALUE:
        return (None,)*nout
    if not isinstance(out, tuple):
        if nout > 1:
            raise TypeError("'out' must be a tuple of arrays")
        out_tuple = (out,)
    else:
        out_tuple = out
    if len(out_tuple) != nout:
        raise ValueError(
            f"The 'out' tuple must have exactly {nout} entries: one per "
            f"ufunc output"
        )
    for entry in out_tuple:
        if entry is not None and not isinstance(entry, np.ndarray):
            raise TypeError("return arrays must be of ArrayType")
    return out_tuple

async def run_out_of_band(async_sessionmaker, statement, merge_results=True):
    """run an ORM statement in a distinct session,
    returning the frozen results
    """

    async with async_sessionmaker() as oob_session:
        # use AUTOCOMMIT for each connection to reduce transaction
        # overhead / contention
        await oob_session.connection(
            execution_options={"isolation_level": "AUTOCOMMIT"}
        )

        result = await oob_session.execute(statement)

        if merge_results:
            return result.freeze()
        else:
            await result.close()

